function initValue() {
	$("#contentSpan").html("<h2 class=\"pgTitle\">기본증명서</h2><div class=\"contentHeader\"><h3 class=\"sTitle\">기재사항</h3><div class=\"headerOption\"><button type=\"button\" name=\"button\" id=\"sampleView\" class=\"sBtnInside btnBlue nw2\" title=\"새창\">견본보기</button></div></div><div class=\"tblGuide\"><table><caption>기본증명서(일반, 상세, 특정)의 공통 기재사항과 개별기재사항에 대한 정보를 제공합니다.</caption><colgroup><col style=\"width: 50px;\"><col style=\"width: 50px;\"><col style=\"width: 160px;\"><col></colgroup><tbody><tr><th colspan=\"2\" scope=\"row\" class=\"\">공통 사항</th><td colspan=\"2\" class=\"tl bgYellow\">본인의 등록기준지, 성명, 성별, 본, 출생연월일, 주민등록번호<span class=\"alInfo small tOrange3 ml5\">특정증명서는 등록기준지, 본 포함여부를 선택할 수 있음</span></td></tr><tr><th rowspan=\"9\" scope=\"rowgroup\">개별<br/>사항</th><th scope=\"row\" class=\"bdL0 bgGray2 tBlack2\">일반</th><td colspan=\"2\" class=\"tl\">본인의 출생, 사망, 국적상실에 관한 사항</td></tr><tr><th scope=\"row\" class=\"bdL0 bgGray2 tBlack2\">상세</th><td colspan=\"2\" class=\"tl\">본인의 출생, 사망, 인지, 친권, 국적, 개명, 성별 등에 관한 사항</td></tr><tr><th rowspan=\"7\" scope=\"rowgroup\" class=\"bdL0 bgGray2 tBlack2\">특정</th><th scope=\"row\" class=\"th2d\">출생&middot;사망&middot;실종</th><td class=\"tl\">본인의 출생, 사망, 실종선고, 주민등록번호 &middot; 출생연월일 정정 등에 관한 사항</td></tr><tr><th scope=\"row\" class=\"bdL0 th2d\">인지&middot;친생자관계정정</th><td class=\"tl\">본인의 인지, 친생부인 등에 관한 사항</td></tr><tr><th rowspan=\"2\" scope=\"row\" class=\"bdL0 th2d\">친권&middot;미성년후견</th><td class=\"tl\"><span class=\"t14 fwB tGray2\">전부)</span> 본인의 친권, 후견, 미성년후견에 관한 모든 사항</td></tr><tr><td class=\"tl bdL0\"><span class=\"t14 fwB tGray2\">현재)</span> 본인의 현재 유효한 친권, 후견, 미성년후견에 관한 사항</td></tr><tr><th scope=\"row\" class=\"bdL0 th2d\">개명&middot;성본변경</th><td class=\"tl\">본인의 개명, 성&middot;본창설, 성&middot;본변경 등에 관한 사항</td></tr><tr><th scope=\"row\" class=\"bdL0 th2d\">국적 취득&middot;상실</th><td class=\"tl\">본인의 귀화, 국적상실, 국적회복 등에 관한 사항</td></tr><tr><th scope=\"row\" class=\"bdL0 th2d\">성별정정</th><td class=\"tl\">본인의 성별정정, 주민등록번호 성별부분 정정 등에 관한 사항</td></tr></tbody></table></div><h3 class=\"sTitle\">교부청구안내</h3><div class=\"boList nov mb5 xs-hidden\"><table><caption>기본증명서의 신청방법별 신청 자격, 수수료, 이용시간, 필요사항에 대한 정보</caption><colgroup><col style=\"width: 100px;\"><col style=\"width: 260px;\"><col style=\"width: 220px;\"><col></colgroup><thead><tr><th scope=\"col\">신청방법</th><th scope=\"col\">인터넷<button type=\"button\" name=\"button\" id=\"goReadIss\" class=\"sBtnInside btnB ml5\">발급하기</button><button type=\"button\" name=\"button\" id=\"issGuide\" class=\"sBtnInside btnB ml5\">발급방법 안내</button></th><th scope=\"col\">무인발급기<button title=\"새창\" type=\"button\" name=\"button\" id=\"lctInq\" class=\"sBtnInside ml5 nw\">위치조회</button></th><th scope=\"col\">방문 (시(구) &middot; 읍 &middot; 면 &middot; 동 사무소)</th></tr></thead><tbody><tr><th scope=\"row\" class=\"bgGray2\">신청자격<sup class=\"ftnote\">1)</sup></th><td>본인, 부모, 배우자, 자녀</td><td>본인</td><td>본인, 배우자, 직계혈족 및 그 대리인</td></tr><tr><th scope=\"row\" class=\"bgGray2\">수수료</th><td>무료</td><td>500원 / 1통</td><td>1,000원 / 1통<button title=\"새창\" type=\"button\" name=\"button\" id=\"feeGuide\" class=\"sBtnInside ml5 nw\">수수료면제 안내</button></td></tr><tr><th scope=\"row\" class=\"bgGray2\">이용시간<sup class=\"ftnote\">2)</sup></th><td>365일 24시간</td><td>발급기에 따라 다름</td><td>평일 09:00~18:00</td></tr><tr><th scope=\"row\" class=\"bgGray2\">필요사항</th><td class=\"vt\"><ul class=\"buList\"><li>인증서<button title=\"새창\" type=\"button\" name=\"button\" id=\"ocertGuide\" class=\"sBtnInside ml5 nw\">인증서 안내</button></li></ul></td><td class=\"vt\"><ul class=\"buList\"><li>지문</li></ul></td><td class=\"vt\"><ul class=\"buList\"><li>주민등록증 등 신분증명서</li><li>신청서<button title=\"새창\" type=\"button\" name=\"button\" id=\"writeSample\" class=\"sBtnInside ml5 nw\">작성예시</button></li><li>위임한 사람의 주민등록증 등 신분증명서</li></ul></td></tr></tbody></table></div><div class=\"tblGuide mb5 lg-hidden md-hidden xs-visible\"><div class=\"tHeader\"><h4>인터넷</h4><button type=\"button\" name=\"button\" id=\"goReadIssM\" class=\"sBtnInside btnB mo-hidden ml5\">발급하기</button><button type=\"button\" name=\"button\" id=\"issGuideM\" class=\"sBtnInside btnB ml5\">발급방법 안내</button></div><table class=\"mb10\"><caption>인터넷으로 신청 시 신청자격, 수수료, 이용시간, 필요사항에 대한 정보를 제공합니다.</caption><colgroup><col style=\"width: 100px;\"><col></colgroup><tbody><tr><th scope=\"row\">신청자격<sup class=\"ftnote\">1)</sup></th><td>본인, 부모, 배우자, 자녀</td></tr><tr><th scope=\"row\">수수료</th><td>무료</td></tr><tr><th scope=\"row\">이용시간<sup class=\"ftnote\">2)</sup></th><td>365일 24시간</td></tr><tr><th scope=\"row\">필요사항</th><td><ul class=\"buList\"><li>인증서<button title=\"새창\" type=\"button\" name=\"button\" class=\"sBtnInside ml5 nw\" id=\"ocertGuideM\">인증서 안내</button></li></ul></td></tr></tbody></table><div class=\"tHeader\"><h4>무인발급기</h4><button title=\"새창\" type=\"button\" name=\"button\" id=\"lctInqM\" class=\"sBtnInside ml5 nw\">위치조회</button></div><table class=\"mb10\"><caption>무인발급기 사용 시 신청자격, 수수료, 이용시간, 필요사항에 대한 정보를 제공합니다.</caption><colgroup><col style=\"width: 100px;\"><col></colgroup><tbody><tr><th scope=\"row\">신청자격<sup class=\"ftnote\">1)</sup></th><td>본인</td></tr><tr><th scope=\"row\">수수료</th><td>500원 / 1통</td></tr><tr><th scope=\"row\">이용시간<sup class=\"ftnote\">2)</sup></th><td>발급기에 따라 다름</td></tr><tr><th scope=\"row\">필요사항</th><td><ul class=\"buList\"><li>지문</li></ul></td></tr></tbody></table><div class=\"tHeader\"><h4>방문 (시(구) &middot; 읍 &middot; 면 &middot; 동 사무소)</h4></div><table><caption>방문 신청 시 신청자격, 수수료, 이용시간, 필요사항에 대한 정보를 제공합니다.</caption><colgroup><col style=\"width: 100px;\"><col></colgroup><tbody><tr><th scope=\"row\">신청자격<sup class=\"ftnote\">1)</sup></th><td>본인, 배우자, 직계혈족 및 그 대리인</td></tr><tr><th scope=\"row\">수수료</th><td>1,000원 / 1통<button title=\"새창\" type=\"button\" name=\"button\" id=\"feeGuideM\" class=\"sBtnInside ml5 nw\">수수료면제 안내</button></td></tr><tr><th scope=\"row\">이용시간<sup class=\"ftnote\">2)</sup></th><td>평일 09:00~18:00</td></tr><tr><th scope=\"row\">필요사항</th><td><ul class=\"buList\"><li>주민등록증 등 신분증명서</li><li>신청서<button title=\"새창\" type=\"button\" name=\"button\" id=\"writeSampleM\" class=\"sBtnInside ml5 nw\">작성예시</button></li><li>위임한 사람의 주민등록증 등 신분증명서</li></ul></td></tr></tbody></table></div><div class=\"guideTxtBox2 mb10\"><dl><dt class=\"fwB\">1) 신청자격</dt><dd class=\"pl15 t14\">다음 각 항에 해당하여 소명자료를 제출하는 경우에는 본인 등이 아닌 경우에도 본인 등의 위임 없이 증명서의 교부를 <span class=\"fwB\">방문</span> 신청할 수 있습니다.<ul class=\"numList\"><li><i>1</i> 국가, 지방자치단체가 직무상 필요 및 법령상 근거에 따라 문서로 신청하는 경우</li><li><i>2</i> 소송, 비송, 민사집행, 보전 등의 각 절차에서 필요한 경우</li><li><i>3</i> 다른 법령에서 본인 등에 관한 증명서를 제출하도록 요구하는 경우</li><li><i>4</i> 민법상의 법정대리인(후견인, 유언집행자, 상속재산관리인, 부재자재산관리인)</li><li><i>5</i> 채권 &middot; 채무 등 재산권의 상속과 관련하여 상속인의 범위를 확인하기 위한 경우</li><li><i>6</i> 보험금 또는 연금의 수급권자를 결정하기 위하여 필요한 때</li><li><i>7</i> <a href=\"https://www.law.go.kr/법령/제주4ㆍ3사건 진상규명 및 희생자 명예회복에 관한 특별법\" target=\"_blank\" title=\"새창\" class=\"refer\">제주4ㆍ3사건 진상규명 및 희생자 명예회복에 관한 특별법</a>제2조제3호의 희생자 본인의 유족에 해당함을 소명하는 자료와 신청인의 신분증명서를 첨부한 때</li><li><i>8</i> <a href=\"https://www.law.go.kr/법령/공익사업을위한토지등의취득및보상에관한법률\" target=\"_blank\" title=\"새창\" class=\"refer\">공익사업을 위한 토지 등의 취득 및 보상에 관한 법률</a>에 따른 공익사업을 수행하는 때에 토지 등의 소유자의 상속인을 확인할 필요가 있는 때</li></ul></dd><dt class=\"fwB mt5\">2) 이용시간</dt><dd class=\"pl15 t14\">장애가 발생하거나 기타 부득이한 사정이 있을 때에는 서비스가 일시적으로 중단될 수 있습니다.</dd></dl></div><h3 class=\"sTitle\">자주하는질문 <a href=\"#\" id=\"faqInq\" class=\"btnMore nw\" title=\"새창\">전체보기</a></h3><div class=\"guideFaqBox\"></div>");
}

/* 안내 페이지 자주하는 질문 삽입 */
function fnCallAjaxGuideFaq() {
	
	var form = $("form[name=guideFaqForm]").serialize();

    $.ajax({
        type : 'post',
        data : form,    
        dataType:"json",
        url :  "/cs/CsGuideFaqListAjax.do",
        success : function(data,status) {
        	fnOnSuccess(data);
        },
        error : function(request,status) {
            alert("조회하는데 실패하였습니다.");
        }
    });
}

function fnOnSuccess(data) {
	
    var htmltext = "";
    
    if(data.resultList.length == 0) {
		return;
    } else {
	    var maxLen = data.resultList.length;
		
	    htmltext += "<ul>";
	    
	    for(var n=0; n < data.resultList.length; n++) {
	        var resultVO = data.resultList[n];
	        var bltnTitle = resultVO.bltnTitle;
	        var bltnCts = resultVO.bltnCts;
	        
	        htmltext += "<li>";
	        htmltext += "<a id=\"title" + String(n) + "\" href=\"javascript:fnShowFaqDtl('" + String(n) + "', " + data.resultList.length + ");\" aria-expanded='false'><i>" + (n + 1) + "</i>" + bltnTitle + "</a>";
	        htmltext += "<div class=\"faqContent\" style=\"display:none;\" id=\"answerTr" + String(n).trim() + "\">" + bltnCts + "</div>";
	        htmltext += "</li>";
	    }
	    
	    htmltext += "</ul>";
    }
    
    $(".guideFaqBox").html(htmltext);
}

/* 자주하는질문 상세보기 */
function fnShowFaqDtl(index, maxIndex) {
	//목록 css 초기화
    for(var i=0; i < maxIndex; i++) {
    	$("#title" + String(i).trim()).removeClass('on');
    	$("#answerTr" + String(i).trim()).css("display", "none");
    }
	
    // 열려있는 모든 답변에 aria-expanded 옵션을 false 로 변경
    $('.guideFaqBox a').attr('aria-expanded', 'false');
    
    //답변 현출 및 비현출
    if(index != selectNum) {
    	$("#title" + index.trim()).addClass('on');
        $("#answerTr" + index.trim()).css("display", "");
        selectNum = index;
        
        // 답변 현출 시 aira-expanded 옵션을 true 로 변경
        $("#title" + index.trim()).attr('aria-expanded', "true");
    } else {
    	selectNum = "";
    }
}

